import{b as o,O as r,g as a,j as e}from"./chunks/framework.DcaUmd3X.js";const i="/assets/image.CFR-1LHD.webp",p=JSON.parse('{"title":"敏捷测试（上）—— 原则与象限","description":"","frontmatter":{},"headers":[],"relativePath":"testing/engineering/agile-testing-1/index.md","filePath":"测试理论与实践/4.现代测试工程/11.敏捷测试（上）.md","lastUpdated":1783947942000}'),n={name:"testing/engineering/agile-testing-1/index.md"};function l(s,t,u,q,g,h){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="敏捷测试-上-——-原则与象限" tabindex="-1">敏捷测试（上）—— 原则与象限 <a class="header-anchor" href="#敏捷测试-上-——-原则与象限" aria-label="Permalink to &quot;敏捷测试（上）—— 原则与象限&quot;">​</a></h1><blockquote><p>在敏捷团队中，测试不只是&quot;测完了告诉你能不能上&quot;——测试人员是质量的&quot;信息提供者&quot;，持续帮助团队看清产品到底处于什么状态。</p></blockquote><blockquote><p>宣言：<a href="https://agilemanifesto.org/iso/zhchs/manifesto.html" target="_blank" rel="noreferrer">敏捷开发者宣言</a></p></blockquote><h2 id="敏捷测试和传统测试有什么不同" tabindex="-1">敏捷测试和传统测试有什么不同 <a class="header-anchor" href="#敏捷测试和传统测试有什么不同" aria-label="Permalink to &quot;敏捷测试和传统测试有什么不同&quot;">​</a></h2><p>传统测试的典型画像是：开发做完 → 扔给测试 → 测试测完 → 报告质量状态。测试是开发之后的一个独立阶段。</p><p>敏捷测试把这个模型翻转了——<strong>测试不是&quot;后面的那个阶段&quot;，而是贯穿整个迭代的持续活动。</strong> 测试人员在需求讨论阶段就参与，在编码阶段写自动化，在迭代结束前做探索式验证。质量不是&quot;测出来的&quot;，是团队在一开始就一起内建的。</p><p>Lisa Crispin 和 Janet Gregory 在《敏捷测试》里总结了敏捷测试的核心基因：</p><blockquote><p><strong>测试人员的存在，不是为了当质量的守门员，而是做质量的信息提供者。</strong></p></blockquote><p>守门员说&quot;不行，不能上&quot;。信息提供者说&quot;目前的状态是这样的：核心功能通过，这三个模块存在中等风险，上次发现的性能问题已修复——你可以据此决策。&quot;</p><h2 id="敏捷测试的七大成功要素" tabindex="-1">敏捷测试的七大成功要素 <a class="header-anchor" href="#敏捷测试的七大成功要素" aria-label="Permalink to &quot;敏捷测试的七大成功要素&quot;">​</a></h2><p>Crispin 和 Gregory 总结了敏捷测试团队成功的七个关键条件，缺一不可：</p><h3 id="_1-全团队对质量负责" tabindex="-1">1. 全团队对质量负责 <a class="header-anchor" href="#_1-全团队对质量负责" aria-label="Permalink to &quot;1. 全团队对质量负责&quot;">​</a></h3><p>测试不是 QA 的工作，是每个人的工作。开发者写单元测试、产品经理在验收时确认功能、测试人员探索高风险区域——没有人可以说&quot;质量不关我的事&quot;。</p><p>这意味着测试人员需要教会团队成员一些基本的测试思维，而开发者需要教会测试人员一些基本的代码和架构知识。</p><h3 id="_2-敏捷测试思维" tabindex="-1">2. 敏捷测试思维 <a class="header-anchor" href="#_2-敏捷测试思维" aria-label="Permalink to &quot;2. 敏捷测试思维&quot;">​</a></h3><p>测试人员的心态要从&quot;按计划执行&quot;切换到&quot;主动创造价值&quot;。不是等需求稳定了再开始写用例，而是在需求还在讨论时就主动提问——&quot;这个场景你考虑过吗？&quot;&quot;如果网络断了这里会发生什么？&quot;</p><p>敏捷测试思维的核心：<strong>拥抱变化，而不是抱怨需求又改了。</strong></p><h3 id="_3-自动化回归测试" tabindex="-1">3. 自动化回归测试 <a class="header-anchor" href="#_3-自动化回归测试" aria-label="Permalink to &quot;3. 自动化回归测试&quot;">​</a></h3><p>没有可靠的自动化回归套件，敏捷的快节奏迭代就是噩梦——每次发布前都要花几天手工回归。<a href="/testing/execution/regression-release.html">回归测试与上线标准</a>已经详细讨论过这一点，这里再强调一次：<strong>自动化回归是敏捷测试的氧气。</strong></p><h3 id="_4-持续反馈" tabindex="-1">4. 持续反馈 <a class="header-anchor" href="#_4-持续反馈" aria-label="Permalink to &quot;4. 持续反馈&quot;">​</a></h3><p>测试的价值不在于&quot;最后的那份报告&quot;，而在于开发过程中的每一次及时反馈——刚写的代码跑一下验收测试、新功能部署到测试环境马上快速探索一轮。反馈越快，问题修复成本越低。</p><h3 id="_5-构建核心工程实践" tabindex="-1">5. 构建核心工程实践 <a class="header-anchor" href="#_5-构建核心工程实践" aria-label="Permalink to &quot;5. 构建核心工程实践&quot;">​</a></h3><p>持续集成、测试驱动开发（TDD）、重构、代码审查——这些工程实践是敏捷测试的基础。如果团队连 CI 都没有，代码合并之后要手动构建部署，测试人员的精力全耗在环境问题上，没时间做真正有价值的测试。</p><h3 id="_6-与客户协作" tabindex="-1">6. 与客户协作 <a class="header-anchor" href="#_6-与客户协作" aria-label="Permalink to &quot;6. 与客户协作&quot;">​</a></h3><p>测试人员不应该只看需求文档去测——文档总有模糊之处。直接和业务方或产品经理沟通：&quot;这个功能的目的是什么？用户最关心的是什么？&quot;有时候一个 30 秒的对话能避免两小时的无效测试。</p><h3 id="_7-关注全局" tabindex="-1">7. 关注全局 <a class="header-anchor" href="#_7-关注全局" aria-label="Permalink to &quot;7. 关注全局&quot;">​</a></h3><p>不要只盯着当前迭代的这几个 stories。上一个迭代的技术债还了吗？下个迭代的功能会不会影响这轮的设计？系统整体的性能趋势在往哪个方向走？</p><p>这也是<a href="/testing/engineering/continuous-delivery-1.html">持续交付（上）</a>和<a href="/testing/engineering/continuous-delivery-2.html">持续交付（下）</a>要解决的问题——把迭代级的测试视角扩展到部署管道全局。</p><h2 id="敏捷测试人员的十条原则" tabindex="-1">敏捷测试人员的十条原则 <a class="header-anchor" href="#敏捷测试人员的十条原则" aria-label="Permalink to &quot;敏捷测试人员的十条原则&quot;">​</a></h2><p>除了团队的七大要素，Crispin 和 Gregory 还总结了测试人员个人的十条行为准则：</p><ol><li><strong>提供持续反馈</strong> —— 不需要等到&quot;测试完成&quot;，有发现随时反馈</li><li><strong>为业务交付价值</strong> —— 测试的终极目标是让用户得到好的产品，不是找到更多 bug</li><li><strong>促进开放沟通</strong> —— 和别人直接对话，而不是只通过 Bug 管理系统交流</li><li><strong>拥抱变化</strong> —— 需求改了不抱怨，而是重新评估&quot;现在风险最高的地方在哪&quot;</li><li><strong>勇于尝试</strong> —— 新工具、新方法、新技术，愿意试试看</li><li><strong>保持简单</strong> —— 测试策略和用例应该简单明了，让人能一眼看懂你的覆盖范围</li><li><strong>持续改进</strong> —— 每个迭代结束后都问自己&quot;测试能不能做得更好？&quot;</li><li><strong>对整个团队负责</strong> —— 不只对测试经理负责，是为整个团队的质量目标服务</li><li><strong>不把 bug 当成绩</strong> —— 找到 bug 不是目的，帮助团队交付好产品才是</li><li><strong>从失败中学习</strong> —— 线上出了问题，不是追究&quot;测试为什么没发现&quot;，而是&quot;我们在哪个环节漏了，流程怎么加固&quot;</li></ol><blockquote><p>这十条中最容易误解的是第 9 条——&quot;不把 bug 当成绩&quot;。不是说不要找 bug，而是说找 bug 的最终目的是提高质量，不要把 bug 数量当 KPI。</p></blockquote><h3 id="测试人员在迭代中的典型节奏" tabindex="-1">测试人员在迭代中的典型节奏 <a class="header-anchor" href="#测试人员在迭代中的典型节奏" aria-label="Permalink to &quot;测试人员在迭代中的典型节奏&quot;">​</a></h3><p>说了这么多原则和理念，落到日常工作中到底是什么样的？假设团队是一个两周的迭代：</p><table tabindex="0"><thead><tr><th>时间点</th><th>做什么</th></tr></thead><tbody><tr><td><strong>迭代启动会</strong></td><td>听需求，主动提问——&quot;这个场景考虑过吗？&quot;&quot;异常情况怎么处理？&quot;，同步开始构思探测章程</td></tr><tr><td><strong>迭代前三天</strong></td><td>和开发一起梳理验收标准，把关键场景写成可执行的验收测试（Q2）。代码可能还没写完，但用例先就绪了</td></tr><tr><td><strong>迭代中期</strong></td><td>自动化验收测试逐步跑通。对刚完成的功能做第一轮探索（Q3），发现问题立刻反馈——不等&quot;提测&quot;，不等&quot;测试阶段&quot;</td></tr><tr><td><strong>迭代后三天</strong></td><td>深度探索高风险区域，补充端到端场景。和产品一起 Demo，验证&quot;做出来的是不是我们想要的&quot;</td></tr><tr><td><strong>迭代回顾会</strong></td><td>不只总结 bug 数量——这轮测试有什么可改进的？哪个环节反复出问题？自动化套件稳定吗？</td></tr></tbody></table><blockquote><p>注意，这里面没有&quot;等开发提测&quot;这个环节。在敏捷中，测试活动从迭代第一天就开始了。</p></blockquote><h2 id="敏捷测试四象限" tabindex="-1">敏捷测试四象限 <a class="header-anchor" href="#敏捷测试四象限" aria-label="Permalink to &quot;敏捷测试四象限&quot;">​</a></h2><p>四象限是《敏捷测试》中最具影响力的框架，由 Brian Marick 最初提出，Crispin 和 Gregory 系统化阐述。它不是一个&quot;要做什么测试&quot;的清单，而是一个<strong>测试规划思维工具</strong>——帮你判断当前缺少哪种测试、应该由谁来做。</p><h3 id="两个维度" tabindex="-1">两个维度 <a class="header-anchor" href="#两个维度" aria-label="Permalink to &quot;两个维度&quot;">​</a></h3><p><img src="'+i+'" alt="alt text"></p><ul><li><strong>纵轴</strong>：面向技术 vs 面向业务——测试用什么语言描述？</li><li><strong>横轴</strong>：支持团队（指导开发） vs 评价产品（发现缺陷）——测试的目的是什么？</li></ul><h3 id="q1-面向技术-·-支持团队-自动化的基本盘" tabindex="-1">Q1：面向技术 · 支持团队（自动化的基本盘） <a class="header-anchor" href="#q1-面向技术-·-支持团队-自动化的基本盘" aria-label="Permalink to &quot;Q1：面向技术 · 支持团队（自动化的基本盘）&quot;">​</a></h3><ul><li><strong>是什么</strong>：单元测试、组件测试、API 接口测试</li><li><strong>谁来做</strong>：开发者为主，SET（测试开发工程师）辅助</li><li><strong>目的</strong>：在编码阶段就发现缺陷，让开发有信心重构</li><li><strong>特点</strong>：完全自动化，作为持续集成的一部分，每次提交都跑</li></ul><p>Q1 是金字塔的底座。Q1 不稳固，上面三个象限都是空中楼阁。</p><h3 id="q2-面向业务-·-支持团队-开发指引" tabindex="-1">Q2：面向业务 · 支持团队（开发指引） <a class="header-anchor" href="#q2-面向业务-·-支持团队-开发指引" aria-label="Permalink to &quot;Q2：面向业务 · 支持团队（开发指引）&quot;">​</a></h3><ul><li><strong>是什么</strong>：用业务语言描述的验收测试、BDD 场景、示例驱动开发</li><li><strong>谁来做</strong>：测试人员和业务方协作编写，开发实现</li><li><strong>目的</strong>：在编码之前就明确&quot;什么叫做完&quot;，消除需求歧义</li><li><strong>特点</strong>：用业务术语编写（如 Gherkin 的 Given-When-Then），开发、测试、业务三方都能看懂</li></ul><p>Q2 的核心价值是<strong>让所有人都对&quot;完成&quot;有相同的理解</strong>。不是&quot;你觉得做完了就是做完了&quot;，而是&quot;这些用例跑通了才算做完&quot;。</p><h3 id="q3-面向业务-·-评价产品-业务验证" tabindex="-1">Q3：面向业务 · 评价产品（业务验证） <a class="header-anchor" href="#q3-面向业务-·-评价产品-业务验证" aria-label="Permalink to &quot;Q3：面向业务 · 评价产品（业务验证）&quot;">​</a></h3><ul><li><strong>是什么</strong>：探索式测试、场景测试、易用性测试、用户验收测试</li><li><strong>谁来做</strong>：测试人员和业务方一起</li><li><strong>目的</strong>：回答&quot;这个产品真的能用吗？用户会觉得好用吗？&quot;</li><li><strong>特点</strong>：以手工测试为主，依赖人的创造力和共情能力</li></ul><p>Q3 是自动化覆盖不到的地方——模拟真实用户的完整操作路径、发现意想不到的行为。脚本测试告诉你&quot;功能是否做了&quot;，探索式测试告诉你&quot;产品是否好用&quot;。</p><h3 id="q4-面向技术-·-评价产品-质量保障" tabindex="-1">Q4：面向技术 · 评价产品（质量保障） <a class="header-anchor" href="#q4-面向技术-·-评价产品-质量保障" aria-label="Permalink to &quot;Q4：面向技术 · 评价产品（质量保障）&quot;">​</a></h3><ul><li><strong>是什么</strong>：性能测试、安全测试、压力测试、兼容性测试</li><li><strong>谁来做</strong>：SET 或专门的性能/安全测试人员</li><li><strong>目的</strong>：评估系统的非功能质量属性</li><li><strong>特点</strong>：工具驱动，大多可自动化，但工具使用门槛较高</li></ul><p><a href="/testing/methodology/security-testing.html">安全测试与渗透测试</a>和<a href="/testing/execution/test-process.html">测试全流程</a>中讲的性能测试都属于 Q4。Q4 的测试往往成本最高，所以要根据风险选择——金融和电商重安全性能，内容类产品可能兼容性和易用性更重要。</p><h3 id="四象限怎么用" tabindex="-1">四象限怎么用 <a class="header-anchor" href="#四象限怎么用" aria-label="Permalink to &quot;四象限怎么用&quot;">​</a></h3><p>不要把四象限当成&quot;四个必须全部填满的框&quot;。它的正确用法是：</p><ul><li><strong>检查测试覆盖的空白</strong>：每个迭代开始前扫一眼——这次迭代我们有没有 Q2 的验收测试？Q3 的探索式测试安排了没有？</li><li><strong>平衡投入</strong>：别把所有精力砸在 Q1 和 Q2（自动化），忘了 Q3（人的判断）；也别只做 Q3 手工探索，Q1 不稳一切都晃</li><li><strong>规划职责</strong>：Q1 主要是开发的事，Q2 是测试+业务+开发协作，Q3 是测试的事，Q4 按风险分</li></ul><blockquote><p>如果一个团队只做 Q1 和 Q2，没有 Q3，他们的产品可能在技术上没问题，但用户会觉得难用。如果一个团队只做 Q3，没有 Q1，他们的测试会越来越慢，因为缺乏自动化底座。</p></blockquote><h3 id="一个容易误解的地方-象限定的是目的-不是类型" tabindex="-1">一个容易误解的地方：象限定的是目的，不是类型 <a class="header-anchor" href="#一个容易误解的地方-象限定的是目的-不是类型" aria-label="Permalink to &quot;一个容易误解的地方：象限定的是目的，不是类型&quot;">​</a></h3><p>很多人会把测试类型和象限绑定——&quot;性能测试永远是 Q4&quot;&quot;单元测试永远是 Q1&quot;。实际上，Crispin 和 Gregory 强调，<strong>象限定位的是测试此刻的目的，不是它的类型标签。</strong></p><p>举个例子，同样是性能测试：</p><ul><li>在开发初期，你写一个简单的负载测试来验证架构设计能否支撑预期的数据量——这时候它是 <strong>Q1（支持团队）</strong>，驱动技术决策</li><li>在发布前，你跑完整的压力测试来评估&quot;当前系统能扛多少并发&quot;——这时候它是 <strong>Q4（评价产品）</strong>，给出质量结论</li></ul><p>再比如探索式测试通常属于 Q3，但在迭代早期用探索式测试快速验证一个技术原型是否可行——这时候它其实是 Q1 的性质，支持开发决策。</p><p><strong>所以怎么判断？不要问&quot;这是什么测试&quot;，要问&quot;这个测试现在用来干什么&quot;。</strong></p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>敏捷测试人员的角色转变：从&quot;守门员&quot;变成&quot;质量信息提供者&quot;——持续反馈，帮助团队决策</li><li>七大成功要素的核心是<strong>全团队对质量负责</strong>和<strong>持续反馈</strong>——测试不是一个人的事</li><li>十条原则中最容易误解的是&quot;不把 bug 当成绩&quot;——目的是帮团队交付好产品，不是攒 bug 数量</li><li>测试人员在整个迭代中持续参与——从启动会提问到回顾会总结，没有&quot;等开发提测&quot;这个环节</li><li>四象限是两个维度交叉：技术/业务 × 支持团队/评价产品。容易误解的一点是——象限定位的是<strong>测试此刻的目的</strong>，不是测试类型标签，同一类测试在不同阶段可以落在不同象限</li><li>四象限是思维工具不是任务清单——用来检查覆盖空白、平衡投入、规划职责</li></ol>',65)])])}const c=o(n,[["render",l]]);export{p as __pageData,c as default};
